style.css:
@-moz-document domain("youtube.com") {
:root {
    color-scheme: light dark;
  }

  /* Base search bar styling */
  .ytSearchboxComponentInputBox {
    background-color: light-dark(#edebeb, #222222);
    border: 1px solid transparent;
    border-radius: 40px;
    padding-left: 15px !important;
    margin-right: 10px;
    transition: all 0.3s ease;
    color: light-dark(#000000, #ffffff);
    position: relative;
  }

  /* Hides icons inside the box when clicked */
  .ytSearchboxComponentInputBox:focus-within svg,
  .ytSearchboxComponentInputBox:focus-within img,
  .ytSearchboxComponentInputBox:focus-within .ytSearchboxComponentSearchIcon,
  .ytSearchboxComponentInputBox:focus-within::before {
    display: none !important;
    visibility: hidden !important;
    opacity: 0 !important;
  }

  /* The Search Button */
  .ytSearchboxComponentSearchButton {
    background-color: light-dark(#edebeb, #222222);
    border: none;
    border-radius: 40px;
    padding: 0 16px;
    min-width: 60px;
    transition: all 0.2s ease;
    color: light-dark(#000000, #ffffff);
    cursor: pointer;
  }

  /* Hover effects (#ff8800) */
  .ytSearchboxComponentInputBox:hover {
    border-color: #365aff;
    box-shadow: 0 0 10px rgba(255, 136, 0, 0.5);
  }

  .ytSearchboxComponentSearchButton:hover {
    background-color: #365aff !important;
    color: #ffffff !important;
  }
}
